/**
 * Gets the authenticated user and their company setup: timezone, US state, compliance system, active modules and key inventory and sales settings. Call once at the start of a session to read dates in the right timezone and to know which compliance- and module-backed tools apply. With several accounts, call it once per account: user, company and settings differ. Pass includePermissions to check what the user may do before a write. isAdmin means full access: every permission plus admin-only actions. myCompany is the user's own company, as api.searchCompanies returns it with isMyCompany: true. When settings.inventory.allowNegativeAvailableQuantity is false, Processing sales orders cannot reserve more than the available quantity for a given product and location. When settings.sales.salesOrderAutofulfill is true, saving a sales order as Processing fills its unfulfilled batch- and package-tracked lines with stock from the line's location. Batches: earliest expiration date, then smallest quantity. Packages: same test result as the line's last package, then earliest expiration date, earliest packaged date, smallest quantity. One line can span several packages.
 */
api.getMe(args: {
  includePermissions?: boolean;
}): Promise<{ user: { id: string; fullName: string | null; email: string; isAdmin: boolean; permissions?: string[] }; myCompany: { id: string; name: string; legalBusinessName: string }; timezone: string; usState: string | null; complianceType: "BIOTRACK" | "METRC" | "NONE" | null; activeModules: ("ANALYTICS" | "API" | "BIOTRACK" | "BLAZE" | "CORE" | "COST_ACCOUNTING" | "CULTIVATION" | "CULTIVATION_ANALYTICS" | "DISTRU_COMMERCE" | "DISTRU_CONNECT" | "DUTCHIE" | "LABEL_PRINTING" | "LEAFLINK" | "METRC" | "QBO" | "ROUTING" | "TREEZ" | "TRYM")[]; settings: { inventory: { allowNegativeAvailableQuantity: boolean; binTrackingEnabled: boolean }; sales: { salesOrderAutofulfill: boolean } } }>
